@Override
    public void incomingDamageEvent(LivingIncomingDamageEvent event, LivingEntity attacker, LivingEntity target, ItemStack stack) {
        if (event.isCanceled() || event.getSource().is(MalumDamageTypes.KARMIC)) {
            return;
        }
        float half = event.getAmount() * 0.5f;
        event.setAmount(half);
        bufferedDamage += half * 1.2f;
    }

@Override
    public void incomingDeathEvent(LivingDeathEvent event, LivingEntity attacker, LivingEntity target, ItemStack stack) {
        if (event.getSource().is(MalumDamageTypes.KARMIC)) {
            event.setCanceled(true);
            target.setHealth(1);
        }
    }

@Override
    public void incomingDeathEvent(LivingDeathEvent event, LivingEntity attacker, LivingEntity target, ItemStack stack) {
        var source = event.getSource();
        if (source.is(Tags.DamageTypes.IS_TECHNICAL)) {
            return;
        }
        if (source.is(MalumDamageTypes.VOID)) {
            return;
        }
        if (target.hasEffect(MalumMobEffects.WYRD_EXHAUSTION)) {
            return;
        }
        if (event.isCanceled()) {
            return;
        }
        if (delay > 0) {
            event.setCanceled(true);
            target.setHealth(1);
            return;
        }
        float health = Easing.SINE_IN_OUT.asWeighedRandom(target.getRandom(), 1, target.getMaxHealth() * 0.66f);
        if (target.level() instanceof ServerLevel serverLevel) {
            for (Entity knockbackTarget : serverLevel.getEntities(target, target.getBoundingBox().inflate(2f), t -> canApplyKnockback(target, t))) {
                knockbackTarget.setDeltaMovement(knockbackTarget.position().subtract(target.position()).normalize().scale(2f).add(0, 0.5f, 0));
            }

            SoundPlayer.create(MalumSoundEvents.WYRD_RECONSTRUCTION).play(target);
            MalumParticleEffectTypes.WYRD_RECONSTRUCTION_REVIVE.createEffect(target)
                    .color(new MalumNetworkedParticleEffectColorData(MalumSpiritTypes.SACRED_SPIRIT, MalumSpiritTypes.INFERNAL_SPIRIT))
                    .customData(new WyrdReconstructionReviveParticleEffect.WyrdReconstructionEffectData(target.getId()))
                    .spawn(serverLevel);
        }
        delay = 15;
        spiritCollectionActivations = TRIGGERS;
        event.setCanceled(true);
        target.setHealth(health);
    }

