        if (status == EntityStatuses.BLOCK_WITH_SHIELD && entity instanceof FrostShielded shielded) {
            if (shielded.hasFrostShield()) {
                SoundHelper.playSoundEvent(entity.getWorld(), entity, WizardsSounds.FROST_SHIELD_IMPACT.soundEvent());
                ci.cancel();
            }
        }
    }

@Inject(method = "isBlocking", at = @At("HEAD"), cancellable = true)
    private void isBlocking_HEAD_FrostShield(CallbackInfoReturnable<Boolean> cir) {
        if (hasFrostShield) {
            cir.setReturnValue(true);
            cir.cancel();
        }
    }

@Inject(method = "blockedByShield", at = @At("HEAD"), cancellable = true)
    private void blockedByShield_HEAD_FrostShield(DamageSource source, CallbackInfoReturnable<Boolean> cir) {
        if (hasFrostShield && !source.isIn(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
            cir.setReturnValue(true);
            cir.cancel();
        }
    }

@Inject(method = "damage", at = @At("HEAD"), cancellable = true)
    private void damage_HEAD_FrostShieldFireImmunity(DamageSource source, float amount, CallbackInfoReturnable<Boolean> cir) {
        if (hasFrostShield && source.isIn(DamageTypeTags.IS_FIRE)) {
            cir.setReturnValue(false);
            cir.cancel();
        }
    }

@Inject(method = "baseTick", at = @At("TAIL"))
    private void baseTick_TAIL_FrostShield(CallbackInfo ci) {
        var entity = (LivingEntity) ((Object)this);
        hasFrostShield = entity.hasStatusEffect(WizardsEffects.frostShield.entry);
        if (hasFrostShield && entity.isOnFire()) {
            entity.extinguish();
        }
    }

public boolean hasFrostShield() {
        return hasFrostShield;
    }

private static Entry frost_shield() {
        var id = Identifier.of(WizardsMod.ID, "frost_shield");
        var name = "Frost Shield";
        var description = "Protects you from attacks, projectiles and fire for {effect_duration} seconds, but also slows down your movement.";
        var spell = SpellBuilder.createSpellActive();
        spell.school = SpellSchools.FROST;
        spell.tier = 3;
        spell.group = HOAR;
        spell.range = 0;

        spell.learn = new Spell.Learn();

        SpellBuilder.Casting.instant(spell);

        spell.release = new Spell.Release();
        spell.release.animation =  PlayerAnimation.of("spell_engine:one_handed_area_release");
        spell.release.sound = new Sound(WizardsSounds.FROST_SHIELD_RELEASE.id());
        spell.release.visuals = Fx.Visuals.of(
                ParticleGroupBuilder.of(SpellEngineParticles.snowflake)
                        .batch(b -> b.shape(ParticleGroup.Shape.PILLAR)
                                .verticalOrigin(ParticleGroupBuilder.Batches.FEET).count(90)
                                .speed(0.1F, 0.35F)),
                ParticleGroupBuilder.of(SpellEngineParticles.frost_shard)
                        .batch(b -> b.shape(ParticleGroup.Shape.PIPE)
                                .widthFactor(2F).verticalOrigin(ParticleGroupBuilder.Batches.FEET)
                                .count(50).speed(0.1F, 0.3F))
        );

        var shield = SpellBuilder.Impacts.effectSet(WizardsEffects.frostShield.id.toString(), 8, 0);
        shield.action.status_effect.show_particles = false;
        spell.impacts = List.of(shield);

        SpellBuilder.Cost.exhaust(spell, 0.3F);
        configureFrostRuneCost(spell);
        SpellBuilder.Cost.cooldown(spell, 30);

        return new Entry(id, spell, name, description).book(Book.FROST);
    }
